start

partition "Interrupt Service Routine" {
    :Receive ISR from PMIC or Temp Sensors;
    :Initiate Safety Protocols;
}

partition "Primary Control Loop" {
    if (Temp >= Early Warning Threshold?) then (Yes)
        fork
            :Spawn Concurrent Monitoring Task 1\n(from Priority Queue);
        fork again
            :Spawn Concurrent Monitoring Task N\n(from Priority Queue);
        end fork
        :Monitor Temperature in Fixed Cycles;
        if (Thermal Stability Confirmed?) then (Yes)
            :Cease Monitoring;
        else (No)
            :Escalate Thermal Response;
            stop
        endif
    else (No - Below Threshold)
        if (Significant Temp Fluctuation?) then (Yes)
            :Acquire Mutex;
            :Log Anomaly to Structured Audit Trail\n(Ring Buffer);
            :Release Mutex;
        else (No)
            :Continue Normal Operation;
        endif
    endif
}

partition "Critical Safety & Verification" {
    :Execute Sensor Fusion;
    :Execute Calibration Routines;
    :Execute Redundancy Management\n(for Out-of-Range Readings);
    :Verify Critical Safety Actions;
}

partition "Asynchronous I/O & Supervision" {
    fork
        :Async Flush Processing Results\nto Non-Volatile Memory\n(Strict I/O Budget);
    fork again
        :Async Flush Audit Logs\nto Non-Volatile Memory\n(Strict I/O Budget);
    end fork
}

partition "Watchdog Supervision" {
    :Watchdog Timer Supervises Sequence;
    if (Sequence Completion OK?) then (Yes)
        :Reset Watchdog;
    else (No - Timeout)
        :Execute Failsafe\nControlled Cool-Down Path;
        stop
    endif
}

stop
@enduml

